insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(801, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Le mal de Pott est une affection: La/Les RF', '[{"l":"A","t":"Caractérisé par une dissémination en règle par voiehématogène","c":true},{"l":"B","t":"La plus fréquente des formes de la tuberculose ostéoarticulaires.","c":true},{"l":"C","t":"A evolution cyclique a3phases.","c":false},{"l":"D","t":"La négativation de l’intradermoréaction à la tuberculine permet d’eliminer le diagnostic.","c":true},{"l":"E","t":"La chirurgie est indiquée lors d’une compression médullaire.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(802, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Dans le mal de POTT, la lésion initiale siège au niveau du:', '[{"l":"A","t":"Disque","c":false},{"l":"B","t":"Apophyse epineuse","c":false},{"l":"C","t":"Corps vertebral","c":true},{"l":"D","t":"Pédicule","c":false},{"l":"E","t":"Lame","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(803, 23, 'Rhumatologie', 'Déviations rachidiennes : scoliose, cyphose', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Parmi les signes cliniques suivants, lequel n’appartient pas au mal de Pott dorso-lombaire ?', '[{"l":"A","t":"La douleur dorso-lombaire","c":false},{"l":"B","t":"La gibbosité dorso-lombaire","c":false},{"l":"C","t":"L’abcès du pli inguinal","c":false},{"l":"D","t":"La tétraplégie","c":true},{"l":"E","t":"La raideur du tronc","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(804, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Quelle(s) est la (ou les) proposition(s) correcte(s)Concernant le mal de Pott ?', '[{"l":"A","t":"Il peut être associé à une tuberculose concomitante située à distance.","c":true},{"l":"B","t":"Il peut correspondre à une réactivation d’une ancienne infection tuberculeuse.","c":true},{"l":"C","t":"Une IDR à la tuberculine négative permet d’éliminer son diagnostic.","c":false},{"l":"D","t":"C’est une forme pauci bacillaire de tuberculose.","c":true},{"l":"E","t":"Il est difficile de faire un diagnostic de certitude","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(805, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Quels sont les facteurs de mauvais pronostic du mal de Pott ?', '[{"l":"A","t":"La paraplégie","c":true},{"l":"B","t":"L’atteinte du disque intervertébral","c":false},{"l":"C","t":"L’âge> à 70 ans","c":true},{"l":"D","t":"La présence d’un abcès froid","c":false},{"l":"E","t":"Non observance thérapeutique","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(806, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Devant une radiographie de spondylodiscite dorsale, quel est l’élément le plus en faveur d ’un mal de Pott parmi les suivants', '[{"l":"A","t":"Érosion marginale antérieure du corps vertébral","c":false},{"l":"B","t":"Osteocondensation des plateaux","c":false},{"l":"C","t":"Fuseau para vertébral","c":true},{"l":"D","t":"Osteophytose","c":false},{"l":"E","t":"Pincement discal","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(807, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Dans un mal de Pott lombaire, la radiographie montre (cochez les réponses justes)', '[{"l":"A","t":"A. Une ostéolyse des plateaux vertébraux","c":true},{"l":"B","t":"Des géodes intra spongieuses","c":true},{"l":"C","t":"Une diminution de la hauteur du disque","c":true},{"l":"D","t":"Pincement des articulaires apophysaires postérieures sur les radiographies de ¾","c":false},{"l":"E","t":"Un fuseau para vertébral","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(808, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant l’examen clinique d’une épaule douloureuse, quels sont les éléments évocateurs d’une tendinopathie simple de la coiffe des rotateurs de rotateurs:', '[{"l":"A","t":"La mobilité passive est toujours limitée","c":false},{"l":"B","t":"Les mouvements actifs peuvent être peu ou pas limites","c":true},{"l":"C","t":"L’atteinte du supra-spinatus est la plus fréquente","c":true},{"l":"D","t":"Les manœuvres du testing n’objectivent pas de résistance","c":false},{"l":"E","t":"Les signes de conflit sont toujours présents","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(809, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Devant une épaule douloureuse chronique avec limitation de la mobilité active et passive et un aspect radiographique normal. Quelle pathologie évoquez-vous ?', '[{"l":"A","t":"Rupture des tendons de la coiffe des rotateurs","c":false},{"l":"B","t":"Tendinopathie du supra-épineux","c":false},{"l":"C","t":"Une bursite algue","c":false},{"l":"D","t":"Une capsulite rétractile","c":true},{"l":"E","t":"Une arthrose gléno-humérale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(810, 32, 'Rhumatologie', 'Fracture de l’humérus', NULL, true, true, 'Concernant l’examen clinique d’une épaule douloureuse: LA RJ', '[{"l":"A","t":"Une douleur mécanique sans limitation des mobilités est en faveur d’une rupture tendineuse","c":false},{"l":"B","t":"Amplitude normale de l’abduction est 120°","c":false},{"l":"C","t":"Une manœuvre de palm up test positive est en faveur d’une attente du tendon supra-épineux","c":false},{"l":"D","t":"Une manœuvre de NEER positive traduit l’existence d’un conflit sous-acromial","c":true},{"l":"E","t":"Une douleur intense avec impotence fonctionnelle traduit une capsulite rétractile","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(811, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant l’épaule douloureuse simple, cochez la ou les réponse (s) juste (s):', '[{"l":"A","t":"L’examen clinique seul permet de poser le diagnostic","c":true},{"l":"B","t":"Il existe parfais un syndrome Inflammation biologique","c":false},{"l":"C","t":"Les radiographies sont le plus souvent normales","c":true},{"l":"D","t":"L’échographie est indispensable pour confirmer le diagnostic","c":false},{"l":"E","t":"Correspond à une rupture partielle de la coiffe des rotateurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(812, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant l’épaule aigue hyper algique, cochez la ou les réponse (s) fausse (s):', '[{"l":"A","t":"L’examen clinique retrouve des amplitudes articulaires normales en mobilité passive, et limites en mobilité active","c":true},{"l":"B","t":"Correspond à une bursite aigue microcristalline","c":false},{"l":"C","t":"Il existe un syndrome Inflammatoire biologique constant","c":true},{"l":"D","t":"La radiographie standard montre le plus souvent une calcification péri-articulaire","c":false},{"l":"E","t":"L’échographie peut mettre en évidence les calcifications de la coiffe des rotateurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(813, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant la capsulite rétractile de l’épaule, quel examen complémentaire qui permet de confirmer le diagnostic:', '[{"l":"A","t":"radiographies standard","c":false},{"l":"B","t":"échographie","c":false},{"l":"C","t":"arthrotographie","c":true},{"l":"D","t":"scintigraphie osseuse","c":false},{"l":"E","t":"imagerie par résonance magnétique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(814, 20, 'Rhumatologie', 'Épaule médicale', NULL, true, true, 'Concernant la capsulite rétractile de l’épaule cocher la ou les réponses fausses', '[{"l":"A","t":"les mobilités actives et passives sont limités","c":false},{"l":"B","t":"la douleur est de type inflammatoire","c":false},{"l":"C","t":"la radiographie et souvent normal au début de l’évolution","c":false},{"l":"D","t":"l’IRM est l’examen de choix pour confirmer le diagnostic","c":true},{"l":"E","t":"Les microtraumatismes sont la cause la plus fréquente","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(815, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant l’épaule douloureuse simple:', '[{"l":"A","t":"L’examencliniqueseulpermetdeposerlediagnostic","c":true},{"l":"B","t":"Il existe parfais un syndrome inflammation biologique","c":false},{"l":"C","t":"Les radiographies sont le plus souvent normales","c":true},{"l":"D","t":"L’échographie est indispensable pour confirmer le diagnostic","c":false},{"l":"E","t":"Correspond a une rupture partielle dela coiffe des rotateurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(816, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant l’épaule aiguë hyper algique: La/Les RF', '[{"l":"A","t":"L’examen clinique retrouve des amplitudes articulaires normales en mobilite passive,et limites en mobilite active","c":true},{"l":"B","t":"Correspond a une bursite aigue microcristalline","c":false},{"l":"C","t":"Il existe un syndrome inflammatoire biologique constant","c":true},{"l":"D","t":"La radiographie standard montre le plus souvent une calcification peri-articulaire","c":false},{"l":"E","t":"L’échographie peut mettre en évidence les calcifications dela coiffe des rotateurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(817, 20, 'Rhumatologie', 'Épaule médicale', NULL, false, true, 'Concernant la capsulite rétractile de l’épaule: La/Les RF', '[{"l":"A","t":"Les mobilites actives et passives sont limites","c":false},{"l":"B","t":"La douleur est de type inflammatoire","c":false},{"l":"C","t":"La radiographie et souvent normal au début de l’évolution","c":false},{"l":"D","t":"L’irm est l’examen de choix pour confirmer le diagnostic","c":true},{"l":"E","t":"Les microtraumatismes sont la cause la plus frequente","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(818, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Une douleur de l’épaule déclenchée par l’abduction du bras et réveillée par la pression localisée sur un point sous- acromial sans aucun signe clinique associé, sans signe radiologique, ni biologique évoque en premier lieu:', '[{"l":"A","t":"Une tendinite simple","c":true},{"l":"B","t":"Une bursite sous-deltoïdienne","c":false},{"l":"C","t":"Une capsulite rétractile","c":false},{"l":"D","t":"Une arthrose gléno-humérale","c":false},{"l":"E","t":"Une rupture de la coiffe des rotateurs","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(819, 21, 'Rhumatologie', 'Arthrite septique', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Quel(s) est (sont) le (s) diagnostic à évoquer devant cette symptomatologie ? La/Les RJ', '[{"l":"A","t":"Entorse de la cheville gauche","c":false},{"l":"B","t":"Tendinite aiguë de la cheville gauche","c":false},{"l":"C","t":"Arthrite septique de la cheville gauche","c":true},{"l":"D","t":"Polyarthrite rhumatoïde débutante","c":false},{"l":"E","t":"Accès aigu de goutte","c":true}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(820, 29, 'Rhumatologie', 'Algoneurodystrophie', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Le diagnostic positif du SDRC (syndrome douloureux régional complexe) repose sur un faisceau d’arguments: La/Les RJ', '[{"l":"A","t":"Tableau clinique évocateur (troubles vasomoteurs, raideur)","c":true},{"l":"B","t":"Contexte étiologique favorisant (traumatisme, immobilisation)","c":true},{"l":"C","t":"Déminéralisation osseuse, avec erosion des surfaces articulaires","c":false},{"l":"D","t":"Hypofixation scintigraphique","c":false},{"l":"E","t":"La VS et la CRP sont normales","c":true}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(821, 18, 'Rhumatologie', 'Amputation et appareillage', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi les propositions suivantes, laquelle (lesquelles) est (sont) exacte (s)?', '[{"l":"A","t":"La détermination du niveau d’amputation dans les causes traumatique ne pose pas de problèmes, les principes généraux sont de garder le maximum d’os, de peau et de membre.","c":true},{"l":"B","t":"L’ostéomyoplastie, est la technique chirurgicale de choix pour réaliser un moignon parfait et adapté à l’appareillage.","c":true},{"l":"C","t":"L’IRM peut indiquer de façon décisive le niveau d’amputation.","c":false},{"l":"D","t":"La résection osseuse doit être plus basse que la section musculaire","c":false},{"l":"E","t":"Les amputations dites « standards » situées à l’union du tiers moyen-tiers supérieur: Ce sont les plus fréquentes.","c":true}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(822, 18, 'Rhumatologie', 'Marche et rééducation', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Concernant la rééducation en traumatologie: La/Les RJ', '[{"l":"A","t":"Le besoin de rééducation repose sur le diagnostic de la maladie, de l’évaluation des déficiences, des limitations d’activité et des restrictions de participation.","c":true},{"l":"B","t":"La phase de récupération après un traumatisme conditionne les différentes phases d’un programme de rééducation. C La chaleur est utilisée comme agent physique antalgique par son action anti-Inflammatoire.","c":true},{"l":"D","t":"Une orthèse est un agent thérapeutique au même titre qu’un medicament.","c":true},{"l":"E","t":"L’arthromoteur est utilisé pour la récupération d’amplitude articulaire par des mobilisations actives.","c":false}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(823, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'L’Atteinte radiologique d’une spondylodiscite tuberculeuse dorsale est caractérisé par: La/Les RJ', '[{"l":"A","t":"Des lésions condensantes des vertèbres adjacentes.","c":false},{"l":"B","t":"Un pincement du disque intervertebral.","c":true},{"l":"C","t":"Une opacité des parties molles en fuseau à l’étage dorsal.","c":true},{"l":"D","t":"Les syndesmophytes.","c":false},{"l":"E","t":"Des macros géodes souvent disposées en miroir de part et d’autre du disque intervertébral.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(824, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, true, true, 'Quels sont les signes en faveur d’une sciatique commune ?', '[{"l":"A","t":"Douleurs et réveils nocturnes","c":false},{"l":"B","t":"Trajet touchant plusieurs racines","c":false},{"l":"C","t":"Notion d’un effort de soulèvement d’une charge","c":true},{"l":"D","t":"Fièvre à 39°C.","c":false},{"l":"E","t":"Présence d’une scoliose.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(825, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, true, true, 'L’examen clinique de la scoliose: LA OU LES RJ', '[{"l":"A","t":"Se fait en position debout et couchée sur un enfant déshabillé","c":true},{"l":"B","t":"De dos, le fil de plomb sert à diagnostiquer une attitude scoliotique","c":false},{"l":"C","t":"Les signes de puberté servent au diagnostic étiologique de la scoliose","c":false},{"l":"D","t":"Les réflexes cutanéo-abdominaux font partie de l’examen clinique","c":false},{"l":"E","t":"La gibbosité est la conséquence de la rotation vertébrale","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(826, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'Une scoliose est une déformation rachidienne:', '[{"l":"A","t":"Dans les deux plans: frontale et sagittale","c":false},{"l":"B","t":"Est définie par la gibbosité","c":true},{"l":"C","t":"Dans le plan frontal, horizontal et sagittal","c":true},{"l":"D","t":"Période la plus à risque d’aggravation: pic de croissance","c":true},{"l":"E","t":"Toutes les réponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(827, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'L’attitude scoliotique est une déviation:', '[{"l":"A","t":"Réductible de la colonne vertébrale par un changement de position","c":true},{"l":"B","t":"Non réductible exactement comme la scoliose","c":false},{"l":"C","t":"Due à une inégalité de longueur des membres inférieurs","c":true},{"l":"D","t":"Due à une Pathologie du bassin ou une attitude antalgique","c":true},{"l":"E","t":"Toutes les réponses sont fausses","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(828, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'la gibbosité d’une scoliose: (cocher la ou les réponses justes)', '[{"l":"A","t":"est une déformation para vertébrale","c":false},{"l":"B","t":"traduit l’inclinaison vertébrale","c":false},{"l":"C","t":"traduit la rotation vertébrale","c":true},{"l":"D","t":"se recherche dos penché en avant","c":true},{"l":"E","t":"est mieux appréciée sur la radiographie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(829, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'La mesure de l’angle de Cobb d’une scoliose se fait:', '[{"l":"A","t":"Sur une radiographie du rachis de profil,","c":false},{"l":"B","t":"A partir du plateau supérieur de la vertèbre limite supérieure et le plateau inférieur de la vertèbre inférieure,","c":true},{"l":"C","t":"À partir du plateau supérieur de la vertèbre sommet et le plateau inférieur de la vertèbre limite inférieur","c":false},{"l":"D","t":"Après correction d’une inégalité de longueur des membres inférieurs,","c":true},{"l":"E","t":"Par mesure du degré de rotation des vertèbres.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(830, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'l’angle de Cobb: cochez la réponse juste:', '[{"l":"A","t":"Permet d’affirmer la scoliose s’il est sup à 20°","c":false},{"l":"B","t":"Permet de chiffrer la scoliose et de surveiller son évolution dans le temps","c":true},{"l":"C","t":"Est l’angle formé par la droite passant par le plateau inférieur de la vertèbre limite supérieur et la droite passant par le plateau supérieur de la vertèbre limite inférieur.","c":false},{"l":"D","t":"Est déterminé par une radiographie de la totalité de la colonne en position debout de profil","c":false},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(831, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, true, true, 'La gibbosité: (la ou les réponses justes)', '[{"l":"A","t":"Est le signe pathognomonique de la scoliose.","c":true},{"l":"B","t":"Traduit l’inclinaison vertébrale.","c":false},{"l":"C","t":"Traduit la rotation vertébrale.","c":true},{"l":"D","t":"Se recherche dos penché en avant.","c":true},{"l":"E","t":"Est mieux appréciée sur la radiographie.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(832, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, true, true, 'En rhumatologie, les orthèses utilisées sont: (la ou les réponses justes)', '[{"l":"A","t":"Les orthèses de repos.","c":true},{"l":"B","t":"Les orthèses de fonction pour les membres.","c":true},{"l":"C","t":"Les orthèses plantaires et chaussures orthopédiques","c":true},{"l":"D","t":"Les orthèses rachidiennes (ceinture de maintien, corset, collier cervical…)","c":true},{"l":"E","t":"Les orthèses de correction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(833, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'La scoliose Idiopathique de l’enfant est caractérisée par:', '[{"l":"A","t":"Une déformation du rachis dans le plan frontal, sagittal et horizontal,","c":true},{"l":"B","t":"L’absence de gibbosité à l’examen clinique,","c":false},{"l":"C","t":"Une inégalité de longueur des membres inférieurs,","c":false},{"l":"D","t":"La présence d’une douleur rachidienne,","c":false},{"l":"E","t":"La présence de signes neurologiques.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(834, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'La scoliose idiopathique:', '[{"l":"A","t":"Est une déformation du rachis complètement réductible sous traitement orthopédique","c":false},{"l":"B","t":"Elle est caractérisée par une attitude antalgique,","c":false},{"l":"C","t":"Elle est suspectée devant un déséquilibre frontal du rachis","c":true},{"l":"D","t":"Elle est secondaire d’une malformation des vertèbres","c":false},{"l":"E","t":"Les corsets de correction de la scoliose sont indiqués à l’âge adulte.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(835, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'L’examen radiologique de la scoliose idiopathique:', '[{"l":"A","t":"Se fait sur un patient en décubitus dorsal","c":false},{"l":"B","t":"Renseigne sur la rotation vertébrale","c":true},{"l":"C","t":"Permet la mesure de l’angle de Cobb,","c":true},{"l":"D","t":"Donne une idée sur le Risser","c":true},{"l":"E","t":"N’est pas demandé systématiquement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(836, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'Le suivi des patients atteint d’une scoliose idiopathique:', '[{"l":"A","t":"Est systématique et obligatoire,","c":true},{"l":"B","t":"Se fait par un examen clinique et radiologique,","c":true},{"l":"C","t":"L’enfant avant la puberté nécessite un suivi rapproché, si l’angle de la scoliose (Cobb=20°) est égale 20°","c":true},{"l":"D","t":"Permet de suivre l’évolution de l’angle de la scoliose.","c":true},{"l":"E","t":"La rééducation n’est pas indispensable au cours du suivi.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(837, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'Le diagnostic clinique de la scoliose idiopathique chez l’enfant se fait devant:', '[{"l":"A","t":"La présence d’une gibbosité,","c":true},{"l":"B","t":"D’un déséquilibre frontal et sagittal du tronc","c":true},{"l":"C","t":"La présence d’une douleur rachidienne","c":false},{"l":"D","t":"La présence de signes neurologiques","c":false},{"l":"E","t":"Une inégalité de longueur des membres inférieurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(838, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'Les scolioses idiopathiques: (Cocher la ou les Réponses justes)', '[{"l":"A","t":"Sont caractérisées par la présence d’une déformation de la colonne vertébrale dans les trois plans de l’espace","c":true},{"l":"B","t":"Elles sont douloureuses chez l’enfant et l’adolescent","c":false},{"l":"C","t":"La gibbosité est un signe clinique d’une attitude scoliotique","c":false},{"l":"D","t":"Le tronc est toujours équilibré en cas de scoliose idiopathique","c":false},{"l":"E","t":"La recherche et la compensation d’une inégalité de longueur des membres inférieurs sont nécessaires avant l’examen cliniques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(839, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'Sur les radiographies en charge du rachis en totalité de face et de profil, une scoliose idiopathique est reconnue par la présence: (Cocher la réponse fausse)', '[{"l":"A","t":"D’une rotation des vertèbres","c":false},{"l":"B","t":"D’un angle de Cobb","c":false},{"l":"C","t":"D’une inclinaison des vertèbres","c":false},{"l":"D","t":"D’une vertèbre sommet et deux vertèbres limites","c":false},{"l":"E","t":"D’une instabilité des vertèbres","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(840, 23, 'Chirurgie pédiatrique', 'Scoliose', NULL, false, true, 'La scoliose idiopathique de l’enfant: (la ou les réponses fausses)', '[{"l":"A","t":"prédomine chez les garçons","c":true},{"l":"B","t":"s’améliore au moment de la puberté","c":true},{"l":"C","t":"comporte une gibbosité lorsque l’enfant se penche en avant","c":false},{"l":"D","t":"se caractérise par une douleur à la percussion des épineuses vertébrale","c":true},{"l":"E","t":"touche les vertèbres lombaires","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(841, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Dans une scoliose on constate que: La/Les RJ', '[{"l":"A","t":"Le déplacement progressif se fait dans les deux plans de l’espace frontale t sagittal.","c":false},{"l":"B","t":"La déviation est réductible de la colonne vertebrale par un changement de position","c":false},{"l":"C","t":"L’appréciation de la gibbosité se fait penché en laterale ten arriere.","c":false},{"l":"D","t":"La mesure de l’angle de Cobb permet de la chiffrer et des ur veille r son evolution.","c":true},{"l":"E","t":"La déformation de l’attitude scoliotique est causée par une mauvaise position.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(842, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’examen clinique de la scoliose: La/Les RJ', '[{"l":"A","t":"Sefaitenpositiondeboutetcouchéesurunenfant déshabillé","c":true},{"l":"B","t":"De dos, le fil de plomb sert à diagnostiquer une attitudes coli oti que","c":false},{"l":"C","t":"Les signes de puberté servent au diagnostic etiologique dela scoliose","c":false},{"l":"D","t":"Les réflexes cutanéo-abdominaux font partie de l’examenclinique","c":false},{"l":"E","t":"La gibbosité est la conséquence de la rotation vertébrale","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(843, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une scoliose est une déformation rachidienne:', '[{"l":"A","t":"Dans les deux plans:frontale t sagittal","c":false},{"l":"B","t":"Est definie parla gibbosite","c":true},{"l":"C","t":"Dans le plan frontal,horizontale t sagittal","c":true},{"l":"D","t":"Période la plus à risque d’aggravation: pic de croissance","c":true},{"l":"E","t":"Toutes les reponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(844, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’angle de Cobb: La RJ', '[{"l":"A","t":"Permet d’affirmer la scolioses’i les t>20°","c":false},{"l":"B","t":"Permet de chiffrer la scoliose et de surveiller son evolution dans l ete mps","c":true},{"l":"C","t":"Est l’angle formé par la droite passant par le plateau inférieur de la vertèbre limite supérieure et la droite passant par le plateau supérieur de la vertebre limite inferieure.","c":false},{"l":"D","t":"Est déterminé par une radiographie de la totalité delacolonneenpositiondeboutdeprofil","c":false},{"l":"E","t":"Toutes les reponses sont fausses.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(845, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La gibbosité d’une scoliose: La/Les RJ', '[{"l":"A","t":"Est une deformation paravertebral e","c":false},{"l":"B","t":"Traduit l’inclinaison vertebrale","c":false},{"l":"C","t":"Traduit la rotation vertebrale","c":true},{"l":"D","t":"Serecherchedospenchéenavant","c":true},{"l":"E","t":"Est mieux appreciee sur la radiographie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(846, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La gibbosité: La/Les RJ', '[{"l":"A","t":"Estlesignepathognomoniquedelascoliose.","c":true},{"l":"B","t":"Traduit l’inclinaison vertebrale.","c":false},{"l":"C","t":"Traduit la rotation vertebrale.","c":true},{"l":"D","t":"Serecherchedospenchéenavant.","c":true},{"l":"E","t":"Est mieux appreciee sur la radiographie.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(847, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les scolioses idiopathiques: La/Les RJ', '[{"l":"A","t":"Sont caractérisées par la présence d’une déformation de la colonne vertébrale dans les trois plansdel’espace","c":true},{"l":"B","t":"Elles sont douloureuses chez l’enfant etl’adolescent","c":false},{"l":"C","t":"La gibbosité est un signe clinique d’une attitude scoliotique","c":false},{"l":"D","t":"Le tronc est toujours équilibré en cas de scoliose idiopathique","c":false},{"l":"E","t":"Larechercheetlacompensationd’une inegalite de longueur des membres inférieurs sont nécessaires avant l’examen cliniques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(848, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Sur les radiographies en charge du rachis en totalité de face et de profil, une scoliose idiopathique est reconnue par la présence: La RF', '[{"l":"A","t":"D’une rotation des vertebres","c":false},{"l":"B","t":"D’un angle de cobb","c":false},{"l":"C","t":"D’une inclinaison des vertebres","c":false},{"l":"D","t":"D’une vertebres om met et deux vertebres limites","c":false},{"l":"E","t":"D’une instabilite des vertebres","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(849, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Dans les scolioses neuromusculaires: La/Les RJ A Les Méningoceles et myéloméningocéles sont de loin les plus fréquentes.', '[{"l":"B","t":"L’élargissement du canal médullaire avec des malformations vertébrales sont souvent retrouvé.","c":true},{"l":"C","t":"IRM n’a pas de rôle dans le diagnostic de ses malformations.","c":false},{"l":"D","t":"Examen neurologique prend toute son importance.","c":true},{"l":"E","t":"Les Moelles bas attachées sont souvent associés à des signes de dysraphismes mineurs.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(850, 23, 'Chirurgie pédiatrique', 'Scoliose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le traitement d’une scoliose est: La/Les RJ', '[{"l":"A","t":"Orthopédique si la preuve de l’évolutivité de la scoliose est établie avec un potentiel de croissance insuffisant pour que la scoliose puisse encore s’aggraver.","c":false},{"l":"B","t":"Débute toujours par la kinésithérapie qui a un rôle à jouer comme traitement d’accompagnement du corset.","c":false},{"l":"C","t":"Le plâtre EDF Permet de diminuer l’angle de Cobb et de mieux préparer la colonne à la mise en place du corset.","c":true},{"l":"D","t":"Chirurgical si l’angle de Cobb dépasse 30°.","c":false},{"l":"E","t":"Chirurgical si échec du TRT par corset durant la croissance.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(851, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, false, 'Parmi les propositions suivantes concernant la scoliose idiopathique (cochez la ou les réponses justes)', '[{"l":"A","t":"Elle est due à une malformation vertébrale.","c":false},{"l":"B","t":"Elle est due à une compensation physiologique d’une inégalité de longueur des membres inférieurs.","c":false},{"l":"C","t":"Elle s’accompagne d’une discontinuité ostéoligamentaire","c":false},{"l":"D","t":"C’est une déviation sinueuse dans les trois plans de l’espace","c":false},{"l":"E","t":"Son diagnostic clinique repose sur la mise en évidence d’une gibbosité à l’examen penché en avant. Q 23. Le bilan radiologique de la scoliose comporte:","c":false},{"l":"A","t":"Radiographie du rachis total de face et profil","c":false},{"l":"B","t":"Radiographie des deux genoux de face","c":false},{"l":"C","t":"Radiographie du bassin de face","c":false},{"l":"D","t":"Radiographie du coude ou de la main","c":false},{"l":"E","t":"Radiographie du pied gauche de profil","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(852, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Les facteurs de risques de la luxation congénitale de la hanche sont: (cochez la ou les réponses justes)', '[{"l":"A","t":"l’antéversion fémorale","c":false},{"l":"B","t":"Un angle acétabulaire ouvert (augmenté)","c":true},{"l":"C","t":"Toutes les Positions de siège","c":false},{"l":"D","t":"Gémellité","c":true},{"l":"E","t":"Primiparité","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(853, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Les facteurs de risque de développement d’une maladie luxante de la hanche chez le nouveau-né sont (cochez la ou les réponses justes)', '[{"l":"A","t":"Antécédent familial de luxation congénitale de hanche","c":true},{"l":"B","t":"Nouveau-né issu d’une grossesse gémellaire","c":true},{"l":"C","t":"Présence d’un torticolis congénital","c":true},{"l":"D","t":"Sexe masculin","c":false},{"l":"E","t":"Présentation céphalique lors de l’accouchement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
