(856, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'En cas de luxation congénitale de la hanche unilatérale: (cochez la ou les réponses justes)', '[{"l":"A","t":"Signe de GALEAZZI est présent","c":true},{"l":"B","t":"Il a une asymétrie de l’attitude spontanée des cuisses","c":true},{"l":"C","t":"Les angles poplités sont limités en bilatéral","c":false},{"l":"D","t":"Il y a plus de plis inguinaux du côté luxé","c":true},{"l":"E","t":"Le pli poplité est plus haut du côté sain","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(857, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Le traitement de la luxation congénitale de la hanche chez le nouveau-né doit:', '[{"l":"A","t":"être entrepris immédiatement","c":true},{"l":"B","t":"faire Appel à un plâtre","c":false},{"l":"C","t":"faire appel à un coussin d’abduction","c":true},{"l":"D","t":"être précédé d’une ténotomie des adducteurs","c":false},{"l":"E","t":"comporter la vérification radiologique du centrage","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(858, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Parmi les éléments suivants; quels sont ceux qui incitent plus particulièrement à rechercher une maladie luxante de la hanche:', '[{"l":"A","t":"grossesse gémellaire","c":true},{"l":"B","t":"malformation des pieds","c":true},{"l":"C","t":"antécédent familial de luxation de hanche","c":true},{"l":"D","t":"malformation rénale","c":false},{"l":"E","t":"présentation par le siège","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(859, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, true, true, 'En cas de de luxation congénitale de la hanche bilatérale chez un nourrisson de 6 mois:', '[{"l":"A","t":"signe de GALEAZZI est évident","c":false},{"l":"B","t":"il ne peut pas y avoir d’asymétrie de l’attitude spontanée des cuisses","c":false},{"l":"C","t":"les ongles poplités sont limités en bilatéral","c":true},{"l":"D","t":"signe de BARLOW est toujours positif","c":false},{"l":"E","t":"le ressaut est toujours présent","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
