(875, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Chez un nouveau-né de 15 jours, Le diagnostic de hanche luxée réductible sans limitation de l’abduction est posé: que proposez-vous comme traitement ? La RJ', '[{"l":"A","t":"L’abstention et le revoir pour l’examiner à l’âge de 4 mois avec une radiographie du bassin.","c":false},{"l":"B","t":"Mise en place d’un langeage en abduction","c":true},{"l":"C","t":"Mise en place d’un harnais de Pavlick","c":false},{"l":"D","t":"Traction au zénith pour respecter le flessum physiologique","c":false},{"l":"E","t":"Traitement chirurgical","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
