(879, 14, 'Chirurgie pédiatrique', 'Déviations et malformations', NULL, false, true, 'Dans les malformations des membres, la maladie amniotique: (cochez la ou les réponses justes)', '[{"l":"A","t":"Est due à une….. Amniotique","c":false},{"l":"B","t":"Le diagnostic est fait par la présence des sillons amniotique","c":true},{"l":"C","t":"Le diagnostic différentiel est fait avec le défaut de formation transversal","c":true},{"l":"D","t":"Est diagnostiquée à la naissance","c":true},{"l":"E","t":"Donne des éctromélie Longitudinales","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(880, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', 'Cas clinique: Un nouveau-né de sexe féminin est adressé à l’âge de 10 jours pour un ressaut de la hanche gauche perçue par le pédiatre à la L’interrogatoire: 4ème enfant, pas de notion familiale de luxation, accouchement normal en présentation Examen clinique: il n’existe ni ressaut, ni Barlow, 6ème doigt surnuméraire, pied-bot varus équin droit. Radiographie du bassin: ailes iliaques asymétriques, latéralisation discrète de la métaphyse gauche. 13.vous retenez en faveur d’une hanche à risque: Source: Q33 -14/15- Sec A Réponse: ABC Source: Q24 -15/16- Sec B Réponse: BDE**', false, true, 'Le diagnostic de LCH doit être retenu: (La ou les réponses justes)', '[{"l":"A","t":"sur la malformation des doigts","c":false},{"l":"B","t":"sur le ressaut perçu à la naissance","c":true},{"l":"C","t":"malgré l’absence d’instabilité au 10ème jour","c":true},{"l":"D","t":"sur la symétrie des aile iliaques","c":false},{"l":"E","t":"sur la latéralisation de la métaphyse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(881, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', 'Cas clinique: Un nouveau-né de sexe féminin est adressé à l’âge de 10 jours pour un ressaut de la hanche gauche perçue par le pédiatre à la L’interrogatoire: 4ème enfant, pas de notion familiale de luxation, accouchement normal en présentation Examen clinique: il n’existe ni ressaut, ni Barlow, 6ème doigt surnuméraire, pied-bot varus équin droit. Radiographie du bassin: ailes iliaques asymétriques, latéralisation discrète de la métaphyse gauche. 13.vous retenez en faveur d’une hanche à risque: Source: Q33 -14/15- Sec A Réponse: ABC Source: Q24 -15/16- Sec B Réponse: BDE**', false, true, 'Classification de SWANSON dans les malformations de membres: (cochez la ou les réponses justes)', '[{"l":"A","t":"Type I: Défaut de différenciation (séparation) des segments","c":false},{"l":"B","t":"Type II: Défaut de formation des segments (arrêt du développement)","c":false},{"l":"C","t":"Type Ill: Duplication","c":true},{"l":"D","t":"Type IV: Hypertrophie (Surdéveloppement- gigantisme)","c":true},{"l":"E","t":"Type VI: Hypotrophie (Sous-développement)","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
