(904, 21, 'Rhumatologie', 'Arthrite septique', NULL, false, true, 'L’épaule aigue hyperalgique:', '[{"l":"A","t":"Réalise un tableau aigu bruyant avec réaction fébrile et une impotence fonctionnelle totale","c":true},{"l":"B","t":"Seuls les mouvements actifs sont limités","c":false},{"l":"C","t":"La ponction articulaire est pratiquée au moindre doute","c":true},{"l":"D","t":"Le diagnostic est radiologique","c":true},{"l":"E","t":"Peut simuler une arthrite septique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(905, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Le germe le plus souvent en cause: (cochez la réponse juste)', '[{"l":"A","t":"Streptocoque,","c":false},{"l":"B","t":"Pneumocoque,","c":false},{"l":"C","t":"Escherichia coli","c":false},{"l":"D","t":"Staphylocoque dore","c":true},{"l":"E","t":"Entérobactérie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(906, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'L’ostéomyélite est une infection aigue de l’os (cochez la ou les propositions justes)', '[{"l":"A","t":"Qui siège au niveau des épiphyses","c":false},{"l":"B","t":"Due le plus souvent au streptocoque","c":false},{"l":"C","t":"Ne survient pas chez le nourrisson avant 1 an","c":false},{"l":"D","t":"Qui touche l’enfant jeune en plein croissance","c":true},{"l":"E","t":"Due à une bactériémie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(907, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Les signes cliniques de l’ostéomyélite sont: (cochez la ou les propositions justes)', '[{"l":"A","t":"Douleur de siège épiphysaire","c":false},{"l":"B","t":"Fièvre","c":true},{"l":"C","t":"Le début est brutal","c":true},{"l":"D","t":"Douleur articulaire bilatérale","c":false},{"l":"E","t":"La présence d’adénopathies est pathognomonique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
