(910, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'En cas d’ostéomyélite aigue, Cochez là où les réponses justes', '[{"l":"A","t":"Avant l’âge de 1 an la propagation épiphysaire est nulle","c":false},{"l":"B","t":"Il y a toujours une porte d’entrée infectieuse","c":false},{"l":"C","t":"Le staphylocoque doré et le plus souvent incriminés","c":true},{"l":"D","t":"L’abcès périosté décolle les artères métaphysaires","c":false},{"l":"E","t":"Bien traiter la CRP se normalise en 3 jours","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(911, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Alors quel est l’examen qui doit être réalisé immédiatement en cas d’hyperthermie ? La/Les RJ', '[{"l":"A","t":"Hémocultures","c":true},{"l":"B","t":"Scintigraphie","c":false},{"l":"C","t":"Prelevement bacteriologique a uni v eau du gros orteil","c":false},{"l":"D","t":"Examen tomodensitometrique","c":false},{"l":"E","t":"Ponction articulaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(912, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le germe le plus souvent en cause: La RJ', '[{"l":"A","t":"Streptocoque,","c":false},{"l":"B","t":"Pneumocoque,","c":false},{"l":"C","t":"Escherichia coli","c":false},{"l":"D","t":"Staphylocoque dore","c":true},{"l":"E","t":"Entérobactérie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(913, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'En cas d’ostéomyélite aiguë: La/Les RJ', '[{"l":"A","t":"Avant l’âge de 1 an la propagation épiphysaire estnulle","c":false},{"l":"B","t":"Ilya toujours une porte d’entree infectieuse","c":true},{"l":"C","t":"Lestaphylocoquedoréetleplussouventincriminés","c":true},{"l":"D","t":"L’abces perioste decolle les arteres metaphysaires","c":false},{"l":"E","t":"Bien traiter l acr pse normalise en3jours","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(914, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’ostéomyélite est une infection aiguë de l’os:', '[{"l":"A","t":"Qui siege a uni v eau des epiphyses","c":false},{"l":"B","t":"Due le plus souvent au streptocoque","c":false},{"l":"C","t":"Ne survient pas chez le nourrisson avant1an","c":false},{"l":"D","t":"Qui touche l’enfant jeune en plein croissance","c":true},{"l":"E","t":"Due a une bacteriemie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(915, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les signes cliniques de l’ostéomyélite sont:', '[{"l":"A","t":"Douleur des iege epiphysaire","c":false},{"l":"B","t":"Fièvre","c":true},{"l":"C","t":"Le debute st brutal","c":true},{"l":"D","t":"Douleur articulaire bilaterale","c":false},{"l":"E","t":"L apres ence d’adenopathies est pathognomonique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(916, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Dans l’ostéomyélite aigue (cochez la réponse juste).', '[{"l":"A","t":"Le nouveau né est rarement atteint","c":false},{"l":"B","t":"Les lésions ne franchissent pas le cartilage de conjugaison","c":true},{"l":"C","t":"L’abcès des parties molles est visible dès le 3ème jour","c":false},{"l":"D","t":"Antibiothérapie et immobilisation sont dépendantes des signes radiologiques","c":false},{"l":"E","t":"Antibiothérapie et immobilisation sont dépendantes des signes radiologiques et biologiques","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(917, 21, 'Chirurgie pédiatrique', 'Arthrite septique', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les signes radiologiques suivants appartiennent à l arthrite septique sauf un. Indiquez lequel:', '[{"l":"A","t":"Ostéophytes","c":true},{"l":"B","t":"Pincement articulaire","c":false},{"l":"C","t":"Géodes en miroir","c":false},{"l":"D","t":"Déminéralisation sous-chondrale","c":false},{"l":"E","t":"Epaississement des parties molles","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(918, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'En pratique, indiquez la cause la plus fréquente d’arthrite septique de l’adulte:', '[{"l":"A","t":"La fixation d’un germe lors d’une bactériémie","c":false},{"l":"B","t":"l’inoculation iatrogène","c":true},{"l":"C","t":"La propagation d’une ostéomyélite de voisinage","c":false},{"l":"D","t":"Une plaie articulaire","c":false},{"l":"E","t":"Une étiologie non retrouvée","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(919, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Devant une suspicion de spondylodiscite d’allure subaiguë, alors que les hémocultures sont négatives et que le début des symptômes cliniques semble remonter approximativement à quatre semaines, quelle est la démarche la plus utile à entreprendre ?', '[{"l":"A","t":"Refaire des hémocultures","c":false},{"l":"B","t":"Demander un examen scannographique","c":false},{"l":"C","t":"Faire une ponction vertébrale en tenant compte de l’information fournie par les clichés tomographiques","c":true},{"l":"D","t":"Mettre en œuvre une antibiothérapie à large spectre sous couvert d’une immobilisation plâtrée","c":false},{"l":"E","t":"Faire faire une scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(920, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'En cas d’infection ostéo-articulaire par voie hématogène chez un enfant de plus de 02ans, quel est le germe le plus fréquemment en cause ?', '[{"l":"A","t":"Le streptocoque viridans.","c":false},{"l":"B","t":"Le streptocoque béta hémolytique.","c":false},{"l":"C","t":"L’hémophilus influenzae.","c":false},{"l":"D","t":"Le staphylocoque blanc.","c":false},{"l":"E","t":"Le staphylocoque doré.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(921, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Sur quels éléments fondez-vous la surveillance de l’efficacité du traitement de l’ostéomyélite aiguë ?', '[{"l":"A","t":"Courbe de température.","c":true},{"l":"B","t":"Protéine C-Réactive (CRP).","c":true},{"l":"C","t":"Radiographie bihebdomadaire.","c":true},{"l":"D","t":"Scintigraphies répétées.","c":false},{"l":"E","t":"Taux des antistaphylolysines.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(922, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Le diagnostic de certitude d’une arthrite seplique à germe banal repose sur la mise en évidence du germe dans', '[{"l":"A","t":"Le liquide céphalo-rachidien","c":false},{"l":"B","t":"Le liquide pleural","c":false},{"l":"C","t":"Le liquide synovial","c":false},{"l":"D","t":"La culture d’une biopsie synoviale","c":false},{"l":"E","t":"Les hémocultures","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(923, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, true, true, 'La paralysie obstétricale du plexus brachial se présente en période néonatale comme: la ou les réponses justes:', '[{"l":"A","t":"Paralysie spastique du membre supérieur.","c":false},{"l":"B","t":"Une raideur articulaire du membre supérieur.","c":false},{"l":"C","t":"Une paralysie flasque du membre supérieur.","c":true},{"l":"D","t":"Une main tombante.","c":false},{"l":"E","t":"Douleur fièvre impotence fonctionnelle absolue du membre supérieur.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(924, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, true, true, 'Dans la paralysie obstétricale du plexus brachial en période néonatale quelle attitude est absolument à éviter ? (Cochez les réponses justes)', '[{"l":"A","t":"Mobiliser le nombre supérieur atteint de l’enfant.","c":false},{"l":"B","t":"Orientez le nouveau-né en rééducation.","c":true},{"l":"C","t":"Demander une radio.","c":false},{"l":"D","t":"Commencez la rééducation la première semaine de vie.","c":true},{"l":"E","t":"Demander un avis spécialisé.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(925, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'À propos de la paralysie obstétrical du plexus brachial: Cocher les réponses justes', '[{"l":"A","t":"la récupération est toujours complète et totale","c":false},{"l":"B","t":"le traitement peut être chirurgicale dans la première année de la vie","c":true},{"l":"C","t":"la paralysie peut s’étendre de l’épaule à la main","c":true},{"l":"D","t":"elle ne peut pas survenir en dehors d’une dystocie des épaules ou d’une rétention de la tête dernière","c":true},{"l":"E","t":"la mise au repos du membre supérieur est obligatoire durant les trois premières semaines de la vie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(926, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, true, true, 'Devant une paralysie obstétricale du plexus brachial (POPB) chez un nouveau-né de 4 jours il faut: cocher la ou les réponses justes', '[{"l":"A","t":"préciser la forme anatomo-clinique","c":false},{"l":"B","t":"orienter le nouveau-né vers un orthopédiste Pédiatre et commencer la rééducation","c":false},{"l":"C","t":"faire un bilan lésionnel rechercher des lésions associés","c":true},{"l":"D","t":"attendre un délai de 21 jours avant de commencer l’immobilisation du membre","c":false},{"l":"E","t":"rechercher l’existence d’une souffrance neonatal qui permet d’orienter le pronostic de la POPB","c":true},{"l":"A","t":"une atteinte des racines nerveuses de C5 à T1","c":false},{"l":"B","t":"une atteinte des racines nerveuses de C5 C6","c":false},{"l":"C","t":"une atteinte des racines nerveuses de C5 à T1 plus le syndrome de Claude Bernard-Horner","c":true},{"l":"D","t":"Des racines nerveuses C5 C6 C7","c":false},{"l":"E","t":"une paralysie totale","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(927, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, true, true, 'La paralysie obstétricale du plexus brachial se présente en période néonatale comme: (la ou les réponses justes)', '[{"l":"A","t":"Une paralysie spastique du membre supérieur.","c":false},{"l":"B","t":"Une raideur articulaire du membre supérieur.","c":false},{"l":"C","t":"Une Paralysie flasque du membre supérieur.","c":true},{"l":"D","t":"Une main tombante.","c":false},{"l":"E","t":"Une main fermée.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(928, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, true, true, 'Dans la paralysie-obstétricale du plexus brachial, l’atteinte de la main est retrouvée dans: (la ou les réponses justes)', '[{"l":"A","t":"Une atteinte des racines nerveuses de C5 à T1","c":true},{"l":"B","t":"Une atteinte des racines nerveuses de C5 C6.","c":false},{"l":"C","t":"Une atteinte des racines nerveuses de C5 à T1 plus le syndrome de Claude Bernard Horner","c":true},{"l":"D","t":"Une atteinte des racines nerveuses C5 C6 C7.","c":false},{"l":"E","t":"Toutes les réponses sont justes.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(929, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'La paralysie obstétricale du plexus brachial (POPB) est: La RJ', '[{"l":"A","t":"Paralysie traumatique","c":true},{"l":"B","t":"Paralysie malformative","c":false},{"l":"C","t":"Paralysie idiopathique","c":false},{"l":"D","t":"Paralysie infectieuse","c":false},{"l":"E","t":"Paralysie tumorale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(930, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'Devant une paralysie obstétricale du plexus brachial chez un nouveau-né de 4 jours il faut:', '[{"l":"A","t":"Préciserlaformeanatomo-clinique","c":true},{"l":"B","t":"Orienter le nouveau-né vers un orthopédiste pediatre et commencer la reeducation","c":false},{"l":"C","t":"Faire un bilan lésionnel rechercher des lésions associés","c":true},{"l":"D","t":"Attendre un delai de21jours avant de commencer l’immobilisation du membre","c":false},{"l":"E","t":"Rechercher l’existence d’une souffrance neonatal qui permet d’orienter le pronostic dela popb","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(931, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'La paralysie obstétricale du plexus brachial se présente en période néonatale comme: La/Les RJ', '[{"l":"A","t":"Paralysie spastique du membres u peri eur.","c":false},{"l":"B","t":"Une raideur articulaire du membres u peri eur.","c":false},{"l":"C","t":"Une paralysie flasque du membres u peri eur.","c":true},{"l":"D","t":"Une main tombante.","c":false},{"l":"E","t":"Douleur, fièvre, impotence fonctionnelle absolue du membresupérieur.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(932, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'Dans la paralysie obstétricale du plexus brachial, l’atteinte de la main est retrouvée dans: Les RJ', '[{"l":"A","t":"Une atteinte des racines nerveuses dec5àT1","c":false},{"l":"B","t":"Une atteinte des racines nerveuses dec5C6","c":false},{"l":"C","t":"Une atteinte des racines nerveuses dec5àT1plus les yndro med e claude-Bernard-Horner","c":true},{"l":"D","t":"Des racines nerveuses c5C6C7","c":false},{"l":"E","t":"Une paralysie totale","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(933, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'Dans la paralysie obstétricale du plexus brachial en période néonatale quelle attitude est absolument à éviter ? Les RJ', '[{"l":"A","t":"Mobiliser le nombre superieur atteint de l’enfant.","c":false},{"l":"B","t":"Orientez le nouveau-neen reeducation.","c":true},{"l":"C","t":"Demander une radio.","c":false},{"l":"D","t":"Commencez la reeducation la1ere semaine devie.","c":true},{"l":"E","t":"Demander un avis specialise.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(934, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'Le Diagnostic anténatal d’une occlusion néonatale est suspecté devant:', '[{"l":"A","t":"Hydramnios","c":true},{"l":"B","t":"Dilations intestinale sur échographie obstétricale.","c":true},{"l":"C","t":"Malformations de la paroi abdominale antérieure.","c":false},{"l":"D","t":"Antécédents familiaux de mucoviscidose.","c":true},{"l":"E","t":"Dosage de la calprotectine fécale,marqueur inflammatoire de souffrance digestive.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(935, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'Les signes de gravité d’une occlusion néonatale, Cochez la ou les réponses justes ?', '[{"l":"A","t":"La notion d’hypotrophie.","c":false},{"l":"B","t":"Laprésence d’un hydramnios sur échographie obstétricale.","c":false},{"l":"C","t":"L’association d’une hypothermie, d’une hypotonie.","c":true},{"l":"D","t":"L’apparition des vomissements fécaloïdes.","c":true},{"l":"E","t":"La présence d’une distension abdominale avec circulation collatérale.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(936, 19, 'Chirurgie pédiatrique', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Les paralysies du plexus brachial après luxation antéro-interne de l’épaule atteignent le plus souvent:', '[{"l":"A","t":"Les 5ème et 6ème racines cervicales","c":false},{"l":"B","t":"Les 7ème, 8ème racines cervicales et 1ère dorsale","c":false},{"l":"C","t":"La 8ème cervicale et la 1ère dorsale","c":false},{"l":"D","t":"Les troncs secondaires du plexus brachial","c":true},{"l":"E","t":"Les racines C5 C6 C8 D1","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(937, 13, 'Chirurgie pédiatrique', 'Membre supérieur et préhension', NULL, false, true, 'La paralysie obstétricale du plexus brachial (POPB) survient à: La/Les RJ', '[{"l":"A","t":"La naissance","c":true},{"l":"B","t":"1er trimestre de grossesse","c":false},{"l":"C","t":"2ème trimestre de grossesse","c":false},{"l":"D","t":"3ème trimestre de grossesse","c":false},{"l":"E","t":"L’enfance.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(938, 1, 'Chirurgie pédiatrique', 'Fractures de l’enfant', NULL, false, true, 'Les fractures supra condyliennes du fémur distal (cocher la ou les réponses justes)', '[{"l":"A","t":"sont des fractures articulaires","c":false},{"l":"B","t":"sont des fractures extra articulaires","c":true},{"l":"C","t":"peuvent entraîner des lésions vasculaires","c":true},{"l":"D","t":"ne se compliquent jamais de raideur","c":false},{"l":"E","t":"sonde de traitement chirurgical le plus souvent","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(939, 1, 'Chirurgie pédiatrique', 'Fractures de l’enfant', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une fracture supra condylienne chez un enfant de 8 ans classée type III selon Lagrange et Rigault, signifie:', '[{"l":"A","t":"Une rupture dela corticale posterieure.","c":false},{"l":"B","t":"Une rupture dela corticale anterieure.","c":false},{"l":"C","t":"Une fracture peu ou pas deplacee.","c":false},{"l":"D","t":"Un déplacement important avec contact inter fragmentaires.","c":true},{"l":"E","t":"Un déplacement important sans contact inter fragmentaires.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(940, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Sur une radiographie du bassin de face strict, en cas de LCH, on analyse:', '[{"l":"A","t":"Un retard d’apparition des noyaux d’ossification","c":true},{"l":"B","t":"Un angle acétabulaire augmenté témoignant de la luxation de hanche","c":false},{"l":"C","t":"La projection des noyaux épiphysaires dans le cadrant inféro-externe témoigne de la luxation de la hanche","c":true},{"l":"D","t":"La présence d’un U radiologique élimine une luxation de la hanche","c":false},{"l":"E","t":"La présence d’un U radiologique témoigne que la tête fémorale a habité le cotyle","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(941, 1, 'Chirurgie pédiatrique', 'Fractures de l’enfant', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les propositions suivantes, quelle(s) est (sont) celle(s) qui s’applique(nt) au syndrome de Volkman:', '[{"l":"A","t":"Il est d’origine ischémique","c":true},{"l":"B","t":"Il atteint surtout les muscles extenseurs de l’avant bras","c":false},{"l":"C","t":"Il peut compliquer une fracture supra condylienne de l’humérus de l’enfant","c":true},{"l":"D","t":"Il peut se traduire seulement par une douleur à l’extension des doigts","c":true},{"l":"E","t":"Il doit être traité d’extrême urgence","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(942, 1, 'Chirurgie pédiatrique', 'Fractures de l’enfant', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le traitement des fractures supra condyliennes chez l’enfant par la méthode de Judet, consiste à: La/Les RJ', '[{"l":"A","t":"Une contention plâtrée en hyper flexion du coude.","c":false},{"l":"B","t":"Un double embrochage parallèle percutané externe.","c":true},{"l":"C","t":"Un embrochage en croix à foyer ouvert.","c":false},{"l":"D","t":"Un double embrochage descendant introduit du V deltoïdien.","c":false},{"l":"E","t":"La mise en place d’une plaque vissée.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(943, 1, 'Chirurgie pédiatrique', 'Fractures de l’enfant', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La fracture en cheveu du tibia (Cochez la ou les réponses fausses)', '[{"l":"A","t":"Elle est fréquente chez l’enfant après rage de 05 ans.","c":false},{"l":"B","t":"Elle se manifeste par une boiterie d’esquive","c":false},{"l":"C","t":"Elle se manifeste par une boiterie de Trendelenburg","c":false},{"l":"D","t":"Elle se manifeste par u refus d’appui","c":false},{"l":"E","t":"La guenson peut être spontanée","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(944, 33, 'Chirurgie pédiatrique', 'Palette humérale et coude', NULL, false, true, 'Les noyaux d’ossification du coude s’ossifient comme suit: La/Les RJ', '[{"l":"A","t":"Le condyle externe entre 6 mois et 2 ans.","c":true},{"l":"B","t":"L’épitrochlée entre 6 et 8 ans.","c":true},{"l":"C","t":"La trochlée entre 10 et 12 ans.","c":true},{"l":"D","t":"L’épicondyle entre 12 et 14 ans.","c":true},{"l":"E","t":"Toutes les réponses sont fausses.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(945, 19, 'Chirurgie pédiatrique', 'Ceinture scapulaire', NULL, false, true, 'La POBP est due à une augmentation brutale de la distance entre: La/Les RJ', '[{"l":"A","t":"Le menton et le thorax.","c":false},{"l":"B","t":"Le menton et l’épaule.","c":true},{"l":"C","t":"Le menton et le cou.","c":false},{"l":"D","t":"Le cou et l’épaule.","c":false},{"l":"E","t":"Le cou et le thorax.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(946, 26, 'Chirurgie pédiatrique', 'Hanche traumatique', NULL, false, true, 'La ponction articulaire en cas d’arthrite de la hanche a: La/Les RJ', '[{"l":"A","t":"Un but diagnostique: voir la nature du liquide et faire l’ECB.","c":true},{"l":"B","t":"Un but thérapeutique: évacuer le liquide et faire un lavage articulaire.","c":true},{"l":"C","t":"Un double but diagnostique et thérapeutique.","c":true},{"l":"D","t":"Peu d’intérêts dans le diagnostic et le traitement de l’arthrite.","c":false},{"l":"E","t":"La ponction articulaire est un acte chirurgical.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(947, 31, 'MPR', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, true, true, 'Le traitement de principe d’une fracture du col du fémur à 85 ans encore valide est: LA RJ', '[{"l":"A","t":"L’abstention thérapeutique","c":false},{"l":"B","t":"Immobilisation simple au lit","c":false},{"l":"C","t":"Le traitement chirurgical","c":true},{"l":"D","t":"L’immobilisation en plâtre pelvi-pédieux","c":false},{"l":"E","t":"La rééducation précoce avec kinésithérapie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(948, 2, 'MPR', 'Marche et rééducation', NULL, true, true, 'Concernant Ia prise en charge de la PR; choisissez la ou les réponse(s) juste(s):', '[{"l":"A","t":"La corticothérapie par voie générale est indiquée dans toutes les formes de la maladie.","c":false},{"l":"B","t":"Le méthotrexate est le traitement de fond de première intention d’une PR a la phase de début","c":true},{"l":"C","t":"Les anti-TNF alfa peuvent étre prescrits en cas d’échec et/ou d’intolérance aux traitements de fond classiques","c":true},{"l":"D","t":"Une atteinte destructrice du genou est une indication une synovectomie","c":false},{"l":"E","t":"Une rééducation active est proposée lors d’une poussée inflammatoire de la maladie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(949, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'Quel serait votre conduite thérapeutique ? Choisissez la ou les réponses justes', '[{"l":"A","t":"Application de glace","c":true},{"l":"B","t":"prescription d’un antalgique seul","c":false},{"l":"C","t":"prescription d’un traitement par AINS","c":true},{"l":"D","t":"entamer une rééducation active","c":false},{"l":"E","t":"prévoir une infiltration locale par un corticoïde retard","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
