(955, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'La prescription de la rééducation (RJs)', '[{"l":"A","t":"nécessite d’abord un bilan initial réalisé par le médecin de MPR (médecine physique de la réadaptation)","c":true},{"l":"B","t":"est un acte de kinésithérapeute","c":false},{"l":"C","t":"est un acte de l’ergothérapeute","c":false},{"l":"D","t":"Elle doit être rédigée sur une ordonnance avec précision des objectifs","c":true},{"l":"E","t":"nécessite une évaluation régulière","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(956, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'Les adjuvants de la rééducation sont:', '[{"l":"A","t":"Des techniques de kinésithérapie","c":false},{"l":"B","t":"Permettent la récupération des amplitudes articulaires et la force musculaire","c":true},{"l":"C","t":"Utilisés chez tous les patients","c":false},{"l":"D","t":"Indispensables dans tout programme rééducatif","c":false},{"l":"E","t":"Assurent l’indolence","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
