(959, 3, 'MPR', 'Marche et rééducation', NULL, true, true, 'La balnéothérapie: la ou les RF', '[{"l":"A","t":"Est une technique de base de kinésithérapie","c":false},{"l":"B","t":"Utilise de l’eau chaude","c":true},{"l":"C","t":"Représente une technique adjuvante antalgique","c":true},{"l":"D","t":"Utilise des eaux thermales","c":true},{"l":"E","t":"Utilise de l’eau de mer","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(960, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'En cas de lésions nerveuses périphériques, la rééducation permet: (réponses justes)', '[{"l":"A","t":"de prévenir les complications cutanées, articulaires et musculaires","c":true},{"l":"B","t":"d’améliorer la fonction","c":true},{"l":"C","t":"une libération du nerf comprimé","c":false},{"l":"D","t":"de guider la récupération sensitive et musculaire.","c":true},{"l":"E","t":"une récupération totale de la fonction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(961, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'Après un traumatisme, le renforcement musculaire:', '[{"l":"A","t":"Fait partie des techniques de kinésithérapie","c":true},{"l":"B","t":"est un adjuvant de la rééducation","c":false},{"l":"C","t":"Se fait en mode statique pendant l’immobilisation","c":true},{"l":"D","t":"Dépend den résultats de l’évaluation musculaire","c":true},{"l":"E","t":"permet l’indolence","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
