(967, 3, 'MPR', 'Marche et rééducation', NULL, false, true, 'La prévention des complications thrombo- emboliques se fait par: (la ou les réponses justes)', '[{"l":"A","t":"Surveillance de l’apparition de douleur et le signe de HOMANS (mollet).","c":true},{"l":"B","t":"Verticalisation précoce.","c":true},{"l":"C","t":"En cas d’œdème, contre-indication de massage de drainage veineux des membres.","c":false},{"l":"D","t":"Prescription d’une héparine de bas poids moléculaire à titre prophylactique.","c":true},{"l":"E","t":"Antibiothérapie par voie générale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(968, 3, 'MPR', 'Marche et rééducation', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', true, true, 'Cocher les réponses justes concernant les complications digestives susceptibles d’émailler l’évolution de ce patient:', '[{"l":"A","t":"Le reflux gastro-œsophagien.","c":true},{"l":"B","t":"Il n’y a pas de risque de constipation grâce à l’alimentation par sonde nasogastrique.","c":false},{"l":"C","t":"Le risque de fausse route.","c":true},{"l":"D","t":"La kinésithérapie a un rôle dans la prévention des complications digestives.","c":false},{"l":"E","t":"le Massage du cadre colique à un intérêt dans la prévention du risque de Constipation.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(969, 3, 'MPR', 'Marche et rééducation', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', false, true, 'La rééducation dans la patho tendineuse: RJ(s)', '[{"l":"A","t":"Autorise l’étirement du tendon 6 semaines après sa rupture","c":false},{"l":"B","t":"Autorise l’étirement du tendon 4 semaines après sa rupture","c":true},{"l":"C","t":"Utilise le massage ponctuel transversal profond","c":false},{"l":"D","t":"Utilise des orthèses en position de détente tendineuse pour permettre la cicatrisation","c":false},{"l":"E","t":"Utilise des mobilisations articulaires actives et passives pendant l’immobilisation","c":true},{"l":"A","t":"Un œdème important.","c":false},{"l":"B","t":"Des rétractions articulaires et péri articulaires entrainant une raideur.","c":true},{"l":"C","t":"Altération de l’état général","c":false},{"l":"D","t":"Une hypersudation","c":false},{"l":"E","t":"Une peau sèche, pâle et atrophique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(970, 3, 'MPR', 'Marche et rééducation', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', false, true, 'Prise en charge non médicamenteuse d’un rhumatisme inflammatoire en phase aiguë: la RJ', '[{"l":"A","t":"Repos","c":false},{"l":"B","t":"Éducation thérapeutique","c":false},{"l":"C","t":"Orthèse de repos, physiothérapie et mobilisations douces","c":true},{"l":"D","t":"Physiothérapie et renforcement (musculaire ???)","c":false},{"l":"E","t":"Infrarouge et massage","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(971, 3, 'MPR', 'Marche et rééducation', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', false, true, 'La prévention de l’enraidissement articulaire et de rétraction musculotendineuse se fait par: RJ(s)', '[{"l":"A","t":"Prescription d’anti inflammatoire","c":false},{"l":"B","t":"Immobilisation articulaire.","c":false},{"l":"C","t":"Prescription de kinésithérapie (mobilisations passives des membres quotidiennes).","c":true},{"l":"D","t":"Position déclive des deux membres inférieurs.","c":false},{"l":"E","t":"Bon positionnement au lit","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(972, 11, 'MPR', 'Boiterie chez l’enfant', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', false, true, 'Au cours d’une boiterie d’esquive: La RJ', '[{"l":"A","t":"L’enfant reduit l ete mps d’appui au sol du membre sain.","c":false},{"l":"B","t":"L’enfant réduit le temps d’appui au sol du membre pathologique.","c":true},{"l":"C","t":"L’enfant n’arrive pas a marcher sur les02membres.","c":false},{"l":"D","t":"L’enfant marche en pliant le genou.","c":false},{"l":"E","t":"L’enfant reduit son perimetre demarche,","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(973, 2, 'MPR', 'Polyarthrite rhumatoïde', 'Cas clinique: « Un homme de 38 ans, arrive au service de Médecine physique et réadaptation 4 semaines après un traumatisme crânien. Il n’a aucun antécédent particulier, il est resté dans le coma pendant 3 semaines et a nécessité une ventilation mécanique pendant cette période. À son arrivée, il présente une hémiplégie droite avec une aphasie, il est porteur d’une sonde naso- gastrique d’alimentation et d’une sonde à demeure. Il n’a pas été levé depuis le traumatisme. »', false, true, 'Concernant Ia prise en charge de la PR:', '[{"l":"A","t":"La corticothérapie par voie générale est indiquée dans toutes les formes dela maladie.","c":false},{"l":"B","t":"Le méthotrexate est le traitement de fond de premièreintentiond’unePRalaphasededébut","c":true},{"l":"C","t":"Les anti-Tnf alfa peuvent etre prescrits en cas d’echec et/ou d’intolerance aux traitements de fond classiques","c":true},{"l":"D","t":"Une atteinte destructrice du genou est une indication une synovectomie","c":false},{"l":"E","t":"Une rééducation active est proposée lors d’une poussee inflammatoire dela maladie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(974, 18, 'MPR', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La rééducation en rhumatologie: La/Les RJ', '[{"l":"A","t":"L’utilisation d’infrarouge permet de réduire l’inflammation;","c":false},{"l":"B","t":"Lors des poussées le renforcement musculaire est dynamique contre resistance.","c":false},{"l":"C","t":"L’auto rééducation est une technique de physiothérapie.","c":false},{"l":"D","t":"L’ergothérapie permet une amélioration des capacites fonctionnelles.","c":true},{"l":"E","t":"Les orthèses sont contre indiquées en cas de poussées.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(975, 18, 'MPR', 'Marche et rééducation', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Après une entorse bénigne ou de gravité moyenne de la cheville: La/Les RJ', '[{"l":"A","t":"La rééducation est mise en oeuvre sans délai, associee a une contention souple ou semi-rig ide.","c":true},{"l":"B","t":"Pendant la periode post-traumatique immediate,le but de la rééducation est de gérer les phénomènes douloureux etde prevenir les complications.","c":true},{"l":"C","t":"L’infrarouge est utilisé à la phase initiale pour la diminution dela douleur.","c":false},{"l":"D","t":"Les mobilisations passives précoces sont contre indiquées.","c":false},{"l":"E","t":"La kinésithérapie se propose de redonner une proprioception normale en utilisant des techniques de reprogrammation neuromusculaire (les exercices de proprioception).","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(976, 18, 'MPR', 'Marche et rééducation', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Concernant la rééducation en traumatologie: La/Les RJ', '[{"l":"A","t":"Le besoin de rééducation repose sur le diagnostic de la maladie, de l’évaluation des déficiences, des limitations d’activite et des restrictions de participation.","c":true},{"l":"B","t":"La phase de récupération après un traumatisme conditionne les differentes phases d’un programme de rééducation.","c":true},{"l":"C","t":"La chaleur est utilisée comme agent physique antalgique par son action anti-Inflammatoire.","c":false},{"l":"D","t":"Une orthèse est un agent thérapeutique au même titrequ’unmedicament.","c":true},{"l":"E","t":"L’arthromoteur est utilisé pour la récupération d’amplitude articulaire par des mobilisations actives.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(977, 18, 'MPR', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La balnéothérapie: La/Les RF', '[{"l":"A","t":"Est une technique de base de kinesitherapie","c":true},{"l":"B","t":"Utilise de l’eau chaude","c":false},{"l":"C","t":"Represente une technique adjuvante antalgique","c":false},{"l":"D","t":"Utilise des eaux thermales","c":false},{"l":"E","t":"Utilise de l’eau deme r","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(978, 42, 'MPR', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La rééducation d’un membre fracture sous plâtre consiste à faire: La/Les RJ', '[{"l":"A","t":"Une surelevation du membre","c":true},{"l":"B","t":"Contraction dynamique des muscles avec charge.","c":false},{"l":"C","t":"Contraction dynamique des muscles sans charge.","c":false},{"l":"D","t":"Contraction dynamique avec resistance","c":false},{"l":"E","t":"Contraction isometriques(statiques)des muscles.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(979, 18, 'MPR', 'Marche et rééducation', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Concernant la rééducation en immersion (La balnéothérapie): Les RJ', '[{"l":"A","t":"Permet un allegement du poids du corps","c":true},{"l":"B","t":"Elle a une ffet antalgique","c":true},{"l":"C","t":"Facilite mouvement","c":true},{"l":"D","t":"C’est une technique de drainage lymphatique","c":false},{"l":"E","t":"Augmente les contraintes sur le foyer fracturaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(980, 18, 'MPR', 'Marche et rééducation', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Prise en charge non médicamenteuse d’une tendinopathie: La RF', '[{"l":"A","t":"Repos","c":false},{"l":"B","t":"Mobilisations ete tir eme nt musculaire","c":false},{"l":"C","t":"Physiothérapie,ultrasons","c":false},{"l":"D","t":"Massage transverse profond","c":false},{"l":"E","t":"Hydrothérapie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(981, 4, 'MPR', 'Situations d’handicap et concept de qualité de vie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La prise en charge des atteintes articulaires dégénératives ou inflamma Readaptation MPR (cochez la/les réponses justes):', '[{"l":"A","t":"Est basée sur des programmes standardis","c":false},{"l":"B","t":"Son élaboration repose sur le modèle conceptuel de la Classification Internationale du Fonctionnement, du handicap et de la santé (CIF)","c":false},{"l":"C","t":"La récupération de la fonction est l’objectif prioritaire","c":false},{"l":"D","t":"Le résultat est mieux acquis par la restauration intégrale de l’anatomie plutôt que par la récupération de la fonction","c":false},{"l":"E","t":"La prise en charge en rééducation doit débuter après firstallation des raideurs articulaires.","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(982, 16, 'MPR', 'Prise en charge des atteintes articulaires (dégénératives et inflammatoires)', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Renforcement musculaire isométrique (réponses justes)', '[{"l":"A","t":"Est un renforcement à vitesse constante","c":false},{"l":"B","t":"Est un renforcement à charge constante","c":false},{"l":"C","t":"Fait partie de la kinésithérapie active","c":false},{"l":"D","t":"Est autorisé en cas de pathologia rhumatismale en poussée.","c":false},{"l":"E","t":"Falt avec une résistance contrôlée par un dynamometre","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(983, 3, 'MPR', 'Marche et rééducation', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions suivantes concemant la balnéothérapie (Cochez la ou les répeonses fausses)', '[{"l":"A","t":"Est une technique de base de kinésithérapie","c":false},{"l":"B","t":"Utilise de l’eau chaude","c":false},{"l":"C","t":"Représente une technique adjuvante antalgique","c":false},{"l":"D","t":"Utilise des eaux thermales","c":false},{"l":"E","t":"Utilise de l’eau de mer","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(984, 3, 'MPR', 'Marche et rééducation', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions suivantes concernant la Médecine Physique et Readapta decine réponses fausses)', '[{"l":"A","t":"La rééducation doit se faire après l’instalation des déficiences","c":false},{"l":"B","t":"La prescription de cefle rééducation est un acte médical mais non obligatoire","c":false},{"l":"C","t":"Les techniques de rééducation doivent être adaptées aux conditions physiques et sociales de l’individu.","c":false},{"l":"D","t":"Les techniques de rééducation doivent être adaptées aux conditions physiques et psychologiques de l’individu","c":false},{"l":"E","t":"Le bilan cinique du patient doit précéder toute prescription de rééducation","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(985, 11, 'MPR', 'Boiterie chez l’enfant', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions suivantes concemant la marche, quelle(s) est (sont) la(es) propositions exactes ?', '[{"l":"A","t":"L’lio-psoas et les ischio-jambiers sont des muscles qui permettent le raccourcissement du membre inférieur en phase cecilante","c":false},{"l":"B","t":"Le triceps sural est un muscle propuseur en fin de phase d’appui","c":false},{"l":"C","t":"La boiterie de Trendelenburg est due à une insuffisance fonctionnelle du quadriceps.","c":false},{"l":"D","t":"Le steppage est un défaut de raccourcissement du membre inférieur gênant le passage du pas en phase cscilante","c":false},{"l":"E","t":"La démarche cérébelleuse est caractérisée par un élargissement du polygone de sustentation.","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(986, 11, 'MPR', 'Marche et rééducation', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions suivantes concernant la boiterie d’esquive (Cochez la ou les réponses justes)', '[{"l":"A","t":"Elle s’observe pour toutes les douleurs du membre inférieur","c":false},{"l":"B","t":"Elle est due à un déficit du muscle moyen fessier (glutéal moyen) du côté de l’appui","c":false},{"l":"C","t":"Elle est due à l’évitement de l’appui du côté douloureux","c":false},{"l":"D","t":"Elle se manifeste par une augmentation du temps d’appui unipodal du coté douloure","c":false},{"l":"E","t":"Elle correspond à une élévation homolatérale du bassin, et une abduction de la hanche","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(987, 11, 'MPR', 'Boiterie chez l’enfant', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La cause principale de la boiterie de Trendelenburg correspond à une insuffisance fonctionnelle du:', '[{"l":"A","t":"muscle quadriceps du côté de l’appui.","c":false},{"l":"B","t":"muscle tibial antérieur du côté de l’appui.","c":false},{"l":"C","t":"muscle moyen fessier (glutéal moyen) du côté controlatéral de l’appui.","c":false},{"l":"D","t":"muscle moyen fessier (glutéal moyen) du côté de l’appui.","c":false},{"l":"E","t":"muscle grand fessier du côté de l’appui. Q 44. La prescription d’appareillage: Cochez la réponse fausse","c":false},{"l":"A","t":"Fait partie des moyens de rééducation","c":false},{"l":"B","t":"Comporte des dispositifs de suppléance extra corporelle","c":false},{"l":"C","t":"Permet le remplacement d’un membre par une orthèse","c":false},{"l":"D","t":"Peut servir à immobiliser un membre","c":false},{"l":"E","t":"Rend plus fonctionnel un membre Q 45. Les facteurs favorisants à l’apparition des escarres sont:","c":false},{"l":"A","t":"Trouble de la sensibilité.","c":false},{"l":"B","t":"Bonne hydratation.","c":false},{"l":"C","t":"hyperprotidémie","c":false},{"l":"D","t":"vieillesse.","c":false},{"l":"E","t":"vascularite. Q 46. La prévention de l’escarre, se fait par:","c":false},{"l":"A","t":"Héparinothérapie à bas poids moléculaire.","c":false},{"l":"B","t":"Retournements, toutes les 2h à 3h.","c":false},{"l":"C","t":"Eviter la macération.","c":false},{"l":"D","t":"Décharger les zones d’appui, en cas de menace d’escarre.","c":false},{"l":"E","t":"La mise en place des bas de contention. Q 47. Un moignon est dit de bonne qualité si: cochez la ou les réponses justes:","c":false},{"l":"A","t":"Il est de forme cylindro-conique","c":false},{"l":"B","t":"La Cicatrice est antérieure","c":false},{"l":"C","t":"La cicatrice est postéro-médiane","c":false},{"l":"D","t":"Il est trop court","c":false},{"l":"E","t":"A la palpation, on note la présence d’exostose Q 48. La prise en charge des atteintes articulaires dégénératives ou inflammatoires en Médecine Physique et de Réadaptation est basée sur:","c":false},{"l":"A","t":"la récupération de la fonction et de la restauration intégrale de l’anatornie,","c":false},{"l":"B","t":"la précocité du traitement rééducatif,","c":false},{"l":"C","t":"la lutte contre la douleur, l’amyotrophie, les raideurs et les déformations,","c":false},{"l":"D","t":"l’évaluation des déficiences, des limitations d’activité, des restrictions de participation,","c":false},{"l":"E","t":"l’évaluation des facteurs environnementaux et facteurs personnels.","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(988, 3, 'MPR', 'Marche et rééducation', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La rééducation d’un patient qui présente un rhumatisme en poussée inflammatoire se base sur:', '[{"l":"A","t":"la décharge de l’articulation malade,","c":false},{"l":"B","t":"la confection des orthèses de repos,","c":false},{"l":"C","t":"la physiothérapie antalgique par le chaud,","c":false},{"l":"D","t":"le renforcement musculaire actif","c":false},{"l":"E","t":"la mobilisation douce. Q 50. Le travail du schéma (ou programme) moteur d’une activité gestuelle, sans autres déficiences associées se fait par le moyen suivant (une seule réponse juste):","c":false},{"l":"A","t":"Gain d’amplitude articulaire","c":false},{"l":"B","t":"Renforcement musculaire","c":false},{"l":"C","t":"La physiothérapie","c":false},{"l":"D","t":"Rééducation sensori-motrice","c":false},{"l":"E","t":"Immobilisation par attelle لا تنسوني من صالح دعائكم","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(989, 14, 'MPR', 'Malformations congénitales du pied chez l’enfant', NULL, true, true, 'Les brides amniotiques au niveau des membres: cocher la ou les réponses justes', '[{"l":"A","t":"sont classer type 2 décalcification de swanson","c":false},{"l":"B","t":"Posent le diagnostic différentiel avec le type 1 qui est le défaut de formation","c":true},{"l":"C","t":"Nécessite toujours une libération de la bride en extrême urgence","c":true},{"l":"D","t":"l’acrosyndactylie en est l’expression clinique parfois","c":true},{"l":"E","t":"toutes les réponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(990, 24, 'MPR', 'Paraplégie', NULL, false, true, 'La paraplégie se caractérise par: (Cocher la ou les Réponses justes)', '[{"l":"A","t":"Perte de la motricité volontaire des quatre membres","c":false},{"l":"B","t":"Perte de la motricité involontaire des deux membres inférieurs","c":false},{"l":"C","t":"Perte de la motricité volontaire des deux membres inférieurs avec ou sans atteinte de tronc","c":false},{"l":"D","t":"Un syndrome pyramidal","c":true},{"l":"E","t":"Elle est toujours d’origine traumatique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
